# Chrome history for refract URLs (if accessible)
$hist = @(
  "$env:LOCALAPPDATA\Google\Chrome\User Data\Default\History",
  "$env:LOCALAPPDATA\Microsoft\Edge\User Data\Default\History"
)
foreach ($h in $hist) {
  if (Test-Path $h) {
    Write-Host "FOUND: $h"
    $tmp = "$env:TEMP\chrome_hist_copy_$(Get-Random).db"
    Copy-Item $h $tmp -Force
    # try sqlite if available
    if (Get-Command sqlite3 -ErrorAction SilentlyContinue) {
      sqlite3 $tmp "SELECT datetime(last_visit_time/1000000-11644473600,'unixepoch','localtime') as t, url FROM urls WHERE url LIKE '%refract%' OR url LIKE '%8080%' OR url LIKE '%8081%' OR url LIKE '%spline%' OR url LIKE '%CONFIGURATOR%' ORDER BY last_visit_time DESC LIMIT 40;"
    } else {
      python -c "import sqlite3; c=sqlite3.connect(r'$tmp'); 
rows=c.execute(\"SELECT datetime(last_visit_time/1000000-11644473600,'unixepoch','localtime'), url FROM urls WHERE url LIKE '%refract%' OR url LIKE '%8080/REFRACT%' OR url LIKE '%8080/CONFIG%' OR url LIKE '%8081%' OR url LIKE '%spline.design%' OR url LIKE '%vercel.app%' ORDER BY last_visit_time DESC LIMIT 50\").fetchall();
[print(r[0], r[1]) for r in rows]" 2>$null
    }
  } else { Write-Host "missing: $h" }
}

