async (page) => {
  // Also peek at CONFIGURATOR_v14 in a new tab WITHOUT leaving v35 as current if possible
  // Actually user said leave the correct one - first verify v35 face has visible shader via pixel sample
  const sample = await page.evaluate(() => {
    const c = document.querySelector('canvas');
    if (!c) return null;
    const gl = c.getContext('webgl2') || c.getContext('webgl');
    // can't easily read WebGL pixels without preserveDrawingBuffer
    return { w: c.width, h: c.height, style: c.style.cssText };
  });
  // Open cfg14 briefly to compare, then RETURN to v35 and stay
  const page2 = await page.context().newPage();
  await page2.goto('http://localhost:8080/CONFIGURATOR_v14_AG.html', { waitUntil: 'domcontentloaded' });
  await page2.waitForTimeout(3500);
